//! # Type Conversion Helpers for Method Shims
//!
//! This module provides type conversion functions used by the generated
//! method shims from `#[miniextendr]` traits. These functions wrap the existing
//! [`TryFromSexp`] and [`IntoR`] traits with appropriate error handling.
//!
//! ## Purpose
//!
//! Method shims generated by `#[miniextendr]` traits need to:
//! 1. Convert `SEXP` arguments to Rust types
//! 2. Convert Rust return values to SEXP
//! 3. Handle conversion errors gracefully (via R errors)
//!
//! This module provides a uniform interface for these conversions.
//!
//! ## Error Handling
//!
//! Conversion and argument-count failures panic with a diagnostic. Generated
//! shims catch them inside `with_r_unwind_protect_shim` and return a tagged
//! condition, so Rust-owned arguments and conversion errors are dropped before
//! returning across the C ABI. A View re-panics with that condition for the
//! consumer's outer boundary. These helpers must not introduce an unguarded
//! Rust panic across a C ABI boundary.
//!
//! ## Thread Safety
//!
//! All functions in this module must be called on R's main thread,
//! as they interact with R's `SEXP` values and error handling.
//!
//! [`TryFromSexp`]: crate::TryFromSexp
//! [`IntoR`]: crate::IntoR

use crate::SEXP;

/// Return R's `NULL` value.
///
/// Convenience function for method shims returning nothing.
///
/// # Safety
///
/// - Must be called on R's main thread (accesses R_NilValue)
///
/// # Returns
///
/// R's `NULL` value (`R_NilValue`)
#[inline]
pub unsafe fn nil() -> SEXP {
    crate::SEXP::nil()
}

/// Convert an R SEXP to a Rust type, panicking on failure.
///
/// Attempts [`TryFromSexp::try_from_sexp`](crate::TryFromSexp::try_from_sexp).
/// Generated shims catch failures with `with_r_unwind_protect_shim`; View
/// result conversions unwind to the consumer's outer boundary.
///
/// # Type Parameters
///
/// * `T` - Target Rust type (must implement [`TryFromSexp`])
///
/// # Arguments
///
/// * `x` - R value to convert
///
/// # Returns
///
/// The converted Rust value.
///
/// # Safety
///
/// - `x` must be a valid SEXP
/// - Must be called on R's main thread
///
/// # Panics
///
/// Panics if conversion fails, using [`TryFromSexp`]'s error type's `Display`
/// impl. The error is dropped during Rust unwinding.
///
/// # Example
///
/// ```ignore
/// // In a method shim:
/// let arg0: i32 = unsafe { from_sexp(argv[0]) };
/// let arg1: String = unsafe { from_sexp(argv[1]) };
/// ```
///
/// [`TryFromSexp`]: crate::TryFromSexp
#[inline]
pub unsafe fn from_sexp<T>(x: SEXP) -> T
where
    T: crate::TryFromSexp,
    T::Error: std::fmt::Display,
{
    match T::try_from_sexp(x) {
        Ok(val) => val,
        Err(e) => panic!("{e}"),
    }
}

/// Convert a Rust value to an R SEXP.
///
/// Calls [`IntoR::into_sexp`](crate::IntoR::into_sexp) to produce an R value.
/// Used in trait ABI method shims for the result, and by a trait's View for
/// each argument, which the shim reads back with [`extract_arg`]
/// (`TryFromSexp`). So a trait-method parameter type needs both directions:
/// the reading markers cross as their inner value
/// ([`AsNumeric`](crate::convert::AsNumeric) as `Option<f64>`, and so on) and
/// [`AsFromStr`](crate::convert::AsFromStr) as its text; `Missing<T>` goes
/// through [`missing_to_sexp`] instead. Parameter checks such as `no_na` run
/// in the implementing method's R-facing wrappers, so they check R arguments,
/// not the typed values a View caller passes.
///
/// # Type Parameters
///
/// * `T` - Source Rust type (must implement [`IntoR`])
///
/// # Arguments
///
/// * `x` - Rust value to convert
///
/// # Returns
///
/// R SEXP representation of the value.
///
/// # Safety
///
/// - Must be called on R's main thread
/// - The returned SEXP must be protected if used across R allocations
///
/// # Example
///
/// ```ignore
/// // In a method shim:
/// let result: f64 = self_ref.area();
/// unsafe { to_sexp(result) }
/// ```
///
/// [`IntoR`]: crate::IntoR
#[inline]
pub unsafe fn to_sexp<T>(x: T) -> SEXP
where
    T: crate::IntoR,
{
    x.into_sexp()
}

/// Convert a `Missing<T>` trait-method argument to the SEXP the vtable shim
/// receives: [`Missing::Absent`](crate::Missing::Absent) is R's
/// missing-argument sentinel, which the shim's `TryFromSexp for Missing<T>`
/// reads back as `Absent` (the same sentinel an R wrapper forwards for an
/// omitted argument), and `Present(value)` converts `value` with
/// [`to_sexp`], so `T` needs `IntoR` like any other argument type
/// (`Missing<AsNumeric>` crosses as the sentinel or the number).
///
/// `Missing<T>` has no `IntoR` impl on purpose: the sentinel is an argument
/// marker, not a value to hand back to R. Only the View's argument array
/// needs this direction.
///
/// # Safety
///
/// Same as [`to_sexp`].
#[inline]
pub unsafe fn missing_to_sexp<T>(x: crate::Missing<T>) -> SEXP
where
    T: crate::IntoR,
{
    match x {
        crate::Missing::Absent => SEXP::missing_arg(),
        crate::Missing::Present(value) => unsafe { to_sexp(value) },
    }
}

/// Convert an R SEXP to a Rust type, returning a Result.
///
/// Unlike [`from_sexp`], this function returns a `Result` instead of
/// panicking on failure. Useful when you want custom error handling.
///
/// # Type Parameters
///
/// * `T` - Target Rust type (must implement [`TryFromSexp`])
///
/// # Arguments
///
/// * `x` - R value to convert
///
/// # Returns
///
/// `Ok(T)` on success, `Err` with the conversion error on failure.
///
/// # Safety
///
/// - `x` must be a valid SEXP
/// - Must be called on R's main thread
///
/// # Example
///
/// ```ignore
/// match unsafe { try_from_sexp::<i32>(argv[0]) } {
///     Ok(val) => { /* use val */ }
///     Err(e) => {
///         // Custom error handling
///         panic!("argument 1: {e}");
///     }
/// }
/// ```
///
/// [`TryFromSexp`]: crate::TryFromSexp
#[inline]
pub unsafe fn try_from_sexp<T>(x: SEXP) -> Result<T, T::Error>
where
    T: crate::TryFromSexp,
{
    T::try_from_sexp(x)
}

// region: Argument extraction helpers

/// Extract and convert an argument from argv with bounds checking.
///
/// Checks that `index < argc` before extracting, and provides a helpful
/// error message if out of bounds.
///
/// # Type Parameters
///
/// * `T` - Target Rust type (must implement [`TryFromSexp`])
///
/// # Arguments
///
/// * `argc` - Number of arguments
/// * `argv` - Pointer to argument array
/// * `index` - Index of argument to extract
/// * `name` - Name of argument (for error messages)
///
/// # Returns
///
/// The converted argument value.
///
/// # Safety
///
/// - If `index` is in range, `argv` must point to at least `argc` valid SEXPs
/// - Must be called on R's main thread
///
/// # Panics
///
/// Panics if `argc` is negative, `index >= argc` (missing argument), or
/// conversion fails. Generated shims run this inside their unwind boundary.
///
/// # Example
///
/// ```ignore
/// // In a method shim for fn foo(&self, x: i32, y: String)
/// let x: i32 = unsafe { extract_arg(argc, argv, 0, "x") };
/// let y: String = unsafe { extract_arg(argc, argv, 1, "y") };
/// ```
///
/// [`TryFromSexp`]: crate::TryFromSexp
#[inline]
pub unsafe fn extract_arg<T>(argc: i32, argv: *const SEXP, index: usize, name: &str) -> T
where
    T: crate::TryFromSexp,
    T::Error: std::fmt::Display,
{
    assert!(
        usize::try_from(argc).is_ok_and(|len| index < len),
        "missing argument: {name}"
    );
    unsafe { from_sexp(*argv.add(index)) }
}

/// Check that the number of arguments matches expected arity.
///
/// # Arguments
///
/// * `argc` - Actual number of arguments
/// * `expected` - Expected number of arguments
/// * `method_name` - Name of method (for error messages)
///
/// # Panics
///
/// Panics if `argc != expected`. Generated vtable shims call this inside
/// `with_r_unwind_protect_shim` so a mismatch uses the tagged-condition
/// transport and unwinds Rust-owned resources before returning.
#[inline]
pub fn check_arity(argc: i32, expected: i32, method_name: &str) {
    assert!(
        argc == expected,
        "{method_name}: expected {expected} arguments, got {argc}"
    );
}
// endregion
